const NOTES = [{ midi: 60, name: 'C4', time: 0, duration: 0.5, velocity: 0.8 }];

async function makeEditor(trackCount = 1, attrs: Record<string, string> = {}) {
  const editor = document.createElement('daw-editor') as any;
  editor.adapter = makeMockAdapter();
  for (const [k, v] of Object.entries(attrs)) editor.setAttribute(k, v);
  document.body.appendChild(editor);
  for (let i = 0; i < trackCount; i++) {
    await editor.addTrack({ name: `T${i}`, midi: { notes: NOTES } });
  }
  await editor.updateComplete;
  return editor;
}

const flush = () => new Promise((r) => setTimeout(r, 0));

describe('<daw-editor> annotation lanes', () => {
  it('renders a lane with positioned boxes for a declarative annotation track', async () => {
    const editor = await makeEditor(); // loaded editor with ≥1 track
    editor.innerHTML +=
      '<daw-annotation-track id="lyrics">' +
      '<daw-annotation id="a" start="1" end="3">Hello</daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const lane = editor.shadowRoot!.querySelector('.annotation-lane');
    expect(lane).toBeTruthy();
    const box = editor.shadowRoot!.querySelector('.annotation-box') as HTMLElement;
    expect(box).toBeTruthy();
    expect(box.getAttribute('data-annotation-id')).toBe('a');
    expect(box.style.left).toBe(Math.floor((1 * editor.effectiveSampleRate) / 1024) + 'px');
    editor.remove();
  });

  it('extends the temporal-mode timeline width to cover an annotation past the audio, and keeps working with indefinite-playback set', async () => {
    const editor = await makeEditor(1, { 'indefinite-playback': '' });
    const annotationEnd = 1000; // seconds — far past the short MIDI-clip duration
    editor.innerHTML += `<daw-annotation-track><daw-annotation start="0" end="${annotationEnd}">x</daw-annotation></daw-annotation-track>`;
    await flush();
    await editor.updateComplete;
    const timeline = editor.shadowRoot!.querySelector('.timeline') as HTMLElement;
    expect(timeline).toBeTruthy();
    const widthPx = parseFloat(timeline.style.width);
    const expectedMin = Math.floor(
      (annotationEnd * editor.effectiveSampleRate) / editor.samplesPerPixel
    );
    expect(widthPx).toBeGreaterThanOrEqual(expectedMin);
    editor.remove();
  });

  it('removing the annotation track removes the lane', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track><daw-annotation start="0" end="1">x</daw-annotation></daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    editor.querySelector('daw-annotation-track')!.remove();
    await flush();
    await editor.updateComplete;
    expect(editor.shadowRoot!.querySelector('.annotation-lane')).toBeNull();
    editor.remove();
  });

  it('re-derives tick annotation seconds when the engine BPM changes', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track id="ticks">' +
      '<daw-annotation id="t1" start-tick="960" end-tick="1920"></daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const el = editor.querySelector('#t1') as HTMLElement & { start: number; end: number };
    // Default 120 BPM, ppqn 960: 960 ticks = 0.5s.
    expect(el.start).toBeCloseTo(0.5);
    editor.bpm = 60;
    await editor.updateComplete;
    await flush();
    expect(el.start).toBeCloseTo(1);
    expect(el.end).toBeCloseTo(2);
    editor.remove();
  });

  it('box-label="id" renders element ids (or 1-based position) in the bars', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track id="s" box-label="id">' +
      '<daw-annotation id="7" start="0" end="1">First line of text</daw-annotation>' +
      '<daw-annotation start="1" end="2">Second line of text</daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const labels = [...editor.shadowRoot!.querySelectorAll('.annotation-box-text')].map((s) =>
      s.textContent?.trim()
    );
    expect(labels).toEqual(['7', '2']); // explicit id, then position fallback
    editor.remove();
  });

  it('box-label="none" renders empty bars even when text exists', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track box-label="none">' +
      '<daw-annotation start="0" end="1">Hidden in lane</daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const label = editor.shadowRoot!.querySelector('.annotation-box-text');
    expect(label?.textContent?.trim()).toBe('');
    editor.remove();
  });

  it('blank-text annotations render as bars and the track works without any list', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track id="regions">' +
      '<daw-annotation start="0" end="1"></daw-annotation>' +
      '<daw-annotation start="1" end="2"></daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    expect(editor.shadowRoot!.querySelectorAll('.annotation-box')).toHaveLength(2);
    const track = editor.querySelector('#regions') as any;
    track.selectNext();
    expect(track.activeAnnotationId).toBeTruthy(); // fully functional, no list anywhere
    editor.remove();
  });

  it('renders the annotation track name in the controls-column lane spacer', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track name="Sections">' +
      '<daw-annotation start="0" end="1">x</daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const spacer = editor.shadowRoot!.querySelector('.annotation-lane-spacer');
    expect(spacer).toBeTruthy();
    expect(spacer!.textContent?.trim()).toBe('Sections');
    editor.remove();
  });

  it('lane spacer stays empty when the annotation track has no name', async () => {
    const editor = await makeEditor();
    editor.innerHTML +=
      '<daw-annotation-track>' +
      '<daw-annotation start="0" end="1">x</daw-annotation>' +
      '</daw-annotation-track>';
    await flush();
    await editor.updateComplete;
    const spacer = editor.shadowRoot!.querySelector('.annotation-lane-spacer');
    expect(spacer!.textContent?.trim()).toBe('');
    editor.remove();
  });
});

/**
 * Canvas editor example.
 *
 * Pointer-move updates stay live, and pointer-up archives them as one undo step.
 */

import { createTravels } from '../src/index';

type Shape = {
  id: string;
  kind: 'rect' | 'ellipse' | 'text';
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  fill: string;
};

type CanvasState = {
  shapes: Shape[];
  selectedIds: string[];
  zoom: number;
};

export const canvasHistory = createTravels<CanvasState>(
  {
    shapes: [],
    selectedIds: [],
    zoom: 1,
  },
  {
    autoArchive: false,
    maxHistory: 500,
  }
);

export function addRectangle(x: number, y: number) {
  canvasHistory.setState((draft) => {
    const id = crypto.randomUUID();
    draft.shapes.push({
      id,
      kind: 'rect',
      x,
      y,
      width: 160,
      height: 96,
      rotation: 0,
      fill: '#3b82f6',
    });
    draft.selectedIds = [id];
  });
  canvasHistory.archive();
}

export function dragSelected(deltaX: number, deltaY: number) {
  canvasHistory.setState((draft) => {
    const selected = new Set(draft.selectedIds);
    for (const shape of draft.shapes) {
      if (selected.has(shape.id)) {
        shape.x += deltaX;
        shape.y += deltaY;
      }
    }
  });
}

export function commitDrag() {
  if (canvasHistory.canArchive()) {
    canvasHistory.archive();
  }
}

export function groupSelected() {
  canvasHistory.setState((draft) => {
    draft.selectedIds.sort();
  });
  canvasHistory.archive();
}

import { findStateCompatibilityIssues } from './compatibility.js';
import { TravelsTypeError } from './errors.js';
import { Travels } from './travels.js';
import type {
  PatchableInput,
  PatchesOption,
  TravelsOptions,
} from './type.js';

/**
 * Create a Travels instance whose state is statically constrained to the
 * durable JSON-shaped subset supported by patches and persistence.
 */
export function createPatchableTravels<
  S,
  F extends boolean = false,
  P extends PatchesOption = {},
>(
  initialState: PatchableInput<S>,
  options?: Omit<
    TravelsOptions<F, true, P>,
    'autoArchive' | 'controlledApply'
  > & {
    autoArchive?: true;
  }
): Travels<S, F, true, P>;

export function createPatchableTravels<
  S,
  F extends boolean = false,
  P extends PatchesOption = {},
>(
  initialState: PatchableInput<S>,
  options: Omit<
    TravelsOptions<F, false, P>,
    'autoArchive' | 'controlledApply'
  > & {
    autoArchive: false;
  }
): Travels<S, F, false, P>;

export function createPatchableTravels<
  S,
  F extends boolean,
  A extends boolean,
  P extends PatchesOption = {},
>(
  initialState: PatchableInput<S>,
  options: TravelsOptions<F, A, P> = {}
): Travels<S, F, A, P> {
  const issues = findStateCompatibilityIssues(initialState, {
    allowFrozen: true,
  });
  if (issues.length > 0) {
    throw new TravelsTypeError(
      'PERSISTENCE_INCOMPATIBLE',
      `Travels: createPatchableTravels received non-durable initial state:\n- ${issues
        .map((issue) => `${issue.path}: ${issue.message}`)
        .join('\n- ')}`
    );
  }
  return new Travels(initialState as S, options);
}

import type { JSONOp, JSONOpComponent, JSONOpList } from 'ot-json1';
import type Content from '../block/base/content';
import type Format from '../block/base/format';
import type { Muya } from '../muya';
import type { ISelection } from '../selection/types';
import type { TState } from '../state/types';
import type { Nullable } from '../types';
import * as otText from 'ot-text-unicode';
import { fromEvent, merge } from 'rxjs';
import { registerBlocks } from '../block';
import { ScrollPage } from '../block/scrollPage';
import Clipboard from '../clipboard';
import { isFirefox } from '../config';
import History from '../history';
import InlineRenderer from '../inlineRenderer';
import { Search } from '../search';
import Selection from '../selection';
import JSONState from '../state';
import { hasPick, isHTMLElement } from '../utils';
import { getBlock } from '../utils/dom';
import logger from '../utils/logger';
import { attachLinkMouseHandlers } from './linkMouseEvents';

const debug = logger('editor:');

export class Editor {
    jsonState: JSONState;
    inlineRenderer: InlineRenderer;
    selection: Selection;
    searchModule: Search;
    clipboard: Clipboard;
    history: History;
    scrollPage: Nullable<ScrollPage> = null;

    private _activeContentBlock: Nullable<Content> = null;

    constructor(public muya: Muya) {
        const state = muya.options.json || muya.options.markdown || '';

        this.jsonState = new JSONState(muya, state);
        this.inlineRenderer = new InlineRenderer(muya);
        this.selection = new Selection(muya);
        this.searchModule = new Search(muya);
        this.clipboard = Clipboard.create(muya);
        this.history = new History(muya);
    }

    get activeContentBlock() {
        return this._activeContentBlock;
    }

    set activeContentBlock(block) {
        const { activeContentBlock: oldActiveContentBlock } = this;
        if (block !== oldActiveContentBlock) {
            this._activeContentBlock = block;
            if (oldActiveContentBlock)
                oldActiveContentBlock.blurHandler();

            if (block)
                block.focusHandler();
        }
    }

    init() {
        registerBlocks();

        const { muya } = this;
        const state = this.jsonState.getState();

        this.scrollPage = ScrollPage.create(muya, state);

        this._dispatchEvents();
        // marktext cb25b3d4 (#1415): hovering a rendered link wrapper
        // dispatches `muya-link-tools` so the staged popover lights up.
        // Cleanup is handled by `muya.destroy()` → `detachAllDomEvents`.
        attachLinkMouseHandlers(muya);
        this.focus();
    }

    private _dispatchEvents() {
        const { domNode } = this.muya;

        const eventHandler = (event: Event) => {
            const { anchorBlock, isSelectionInSameBlock }
                = this.selection.getSelection() ?? {};
            // Fix issue that language input can not get focus when it's empty(Firefox only)
            if (
                event.type === 'click'
                && isFirefox
                && isHTMLElement(event.target)
                && event.target.textContent === ''
                && event.target.classList.contains('mu-language-input')
            ) {
                (getBlock(event.target) as Content | undefined)?.setCursor(0, 0, true);
                return;
            }

            if (!isSelectionInSameBlock || !anchorBlock) {
                this.activeContentBlock = null;
                return;
            }

            this.activeContentBlock = anchorBlock;

            switch (event.type) {
                case 'click': {
                    anchorBlock.clickHandler(event);
                    break;
                }
                case 'input': {
                    anchorBlock.inputHandler(event);
                    break;
                }
                case 'keydown': {
                    anchorBlock.keydownHandler(event);
                    break;
                }
                case 'keyup': {
                    anchorBlock.keyupHandler(event);
                    break;
                }
                case 'compositionend':
                case 'compositionstart': {
                    anchorBlock.composeHandler(event);
                    break;
                }
            }
        };

        merge(
            fromEvent(domNode, 'click'),
            fromEvent(domNode, 'input'),
            fromEvent(domNode, 'keydown'),
            fromEvent(domNode, 'keyup'),
            fromEvent(domNode, 'compositionend'),
            fromEvent(domNode, 'compositionstart'),
        ).subscribe(eventHandler);
    }

    focus() {
    // TODO: the cursor maybe passed by muya options.cursor, and no need to find the first leaf block.
        const firstLeafBlock = this.scrollPage?.firstContentInDescendant();

        if (firstLeafBlock == null)
            return;

        const cursor = {
            path: firstLeafBlock.path,
            block: firstLeafBlock,
            anchor: {
                offset: 0,
            },
            focus: {
                offset: 0,
            },
        };

        const needUpdated
            = firstLeafBlock.blockName === 'paragraph.content'
                && (firstLeafBlock as Format).checkNeedRender(cursor);

        firstLeafBlock.setCursor(0, 0, needUpdated);
    }

    updateContents(operations: JSONOp, selection: Nullable<ISelection>, source: string) {
        const { muya } = this;
        // ot-json1 no-op (`null`) is forwarded to dispatch — JSONState
        // short-circuits internally so listeners still see a json-change
        // event for the no-op.
        this.jsonState.dispatch(operations, source);

        // Codes bellow are copy from `ot-json1.apply` and modified.
        if (operations === null)
            return;

        // The pick/drop walkers operate on live block-tree nodes (ScrollPage,
        // Parent, Content). The tree's instance methods (queryBlock, find,
        // insertBefore, etc.) are not all exposed on a single TS type, and
        // ot-json1 op descents are dynamically shaped — so we type these as
        // BlockNode (loose structural alias) inside the inner walkers and let
        // the runtime branches do the actual narrowing.
        type BlockNode = {
            queryBlock?: (path: (string | number)[]) => BlockNode | undefined;
            find?: (key: number | string) => BlockNode;
            remove?: (source: string) => void;
            replaceWith?: (newBlock: BlockNode, source: string) => void;
            insertBefore?: (newBlock: BlockNode, ref: BlockNode, source: string) => void;
            update?: (value?: unknown, source?: string) => void;
            blockName?: string;
            align?: string;
            _text?: string;
            text?: string;
            meta?: { lang?: string; type?: string };
            parent?: BlockNode;
        } | undefined;

        // Phase 1: Pick. Returns updated subDocument.
        function pick(subDoc: BlockNode, descent: JSONOpList): BlockNode {
            const stack: BlockNode[] = [];

            let i = 0;

            for (; i < descent.length; i++) {
                const d = descent[i];
                if (Array.isArray(d))
                    break;
                if (typeof d === 'object')
                    continue;
                stack.push(subDoc);
                // Its valid to descend into a null space - just we can't pick there.
                subDoc = subDoc == null ? undefined : subDoc.queryBlock?.([d]);
            }

            // Children. These need to be traversed in reverse order here.
            for (let j = descent.length - 1; j >= i; j--)
                subDoc = pick(subDoc, descent[j] as JSONOpList);

            // Then back again.
            for (--i; i >= 0; i--) {
                const d = descent[i];
                if (typeof d !== 'object') {
                    const container = stack.pop();
                    if (
                        subDoc
                        === (container == null ? undefined : container.queryBlock?.([d as string | number]))
                    ) {
                        subDoc = container;
                    }
                    else {
                        if (subDoc === undefined) {
                            // TODO: handler typeof d === 'string'
                            if (typeof d === 'number')
                                container?.find?.(d)?.remove?.('api');
                            subDoc = container;
                        }
                        else {
                            if (typeof d === 'number')
                                container?.find?.(d)?.replaceWith?.(subDoc, 'api');
                            subDoc = container;
                        }
                    }
                }
                else if (!Array.isArray(d) && hasPick(d)) {
                    subDoc = undefined;
                }
            }

            return subDoc;
        }

        const snapshot = pick(this.scrollPage as BlockNode, operations);

        function drop(root: BlockNode, descent: JSONOpList): BlockNode {
            let subDoc = root;
            let i = 0; // For reading
            let m = 0;
            const rootContainer: { root: BlockNode } = { root }; // This is an avoidable allocation.
            let container: BlockNode | { root: BlockNode } = rootContainer;
            let key: string | number = 'root'; // For writing

            function mut() {
                for (; m < i; m++) {
                    const d = descent[m];
                    if (typeof d === 'object')
                        continue;
                    if (key === 'root') {
                        const wrap = container as { root: BlockNode };
                        container = wrap.root;
                    }
                    else {
                        container = (container as BlockNode)?.queryBlock?.([key]);
                    }
                    key = d as string | number;
                }
            }

            for (; i < descent.length; i++) {
                const d = descent[i];

                if (Array.isArray(d)) {
                    const child = drop(subDoc, d);
                    if (child !== subDoc && child !== undefined) {
                        mut();
                        // It maybe never go into this if statement.
                        if (key === 'root')
                            (container as { root: BlockNode }).root = child;
                        else
                            (container as Record<string, BlockNode>)[key] = child;
                        subDoc = child;
                    }
                }
                else if (typeof d === 'object') {
                    const comp = d as JSONOpComponent;
                    if (comp.i !== undefined) {
                        // Insert
                        mut();
                        const cur = container as BlockNode;
                        const ref = cur?.find?.(key);
                        if (typeof key === 'number') {
                            const insertedState = comp.i as { name: string };
                            const newBlock = ScrollPage.loadBlock(insertedState.name).create(muya, insertedState) as BlockNode;
                            if (cur && ref && newBlock)
                                cur.insertBefore?.(newBlock, ref, 'api');

                            subDoc = newBlock;
                        }
                        else {
                            switch (key) {
                                case 'checked': {
                                    ref?.update?.(comp.i, 'api');
                                    break;
                                }

                                case 'meta':
                                    // Do nothing.
                                    break;

                                default:
                                    debug.warn(`Unknown operation path ${key}`);
                                    break;
                            }
                        }
                    }

                    if (comp.es) {
                        // Edit. Ok because its illegal to drop inside mixed region
                        mut();
                        const sd = subDoc!;
                        if (sd.blockName === 'table.cell') {
                            sd.align = otText.type.apply(sd.align ?? '', comp.es) as string;
                        }
                        else if (sd.blockName === 'language-input') {
                            sd._text = otText.type.apply(sd.text ?? '', comp.es) as string;
                            if (sd.parent?.meta)
                                sd.parent.meta.lang = sd.text;
                            sd.update?.();
                        }
                        else if (sd.blockName === 'code-block') {
                            // Handle modify code block type.
                            if (sd.meta)
                                sd.meta.type = otText.type.apply(sd.meta.type ?? '', comp.es) as string;
                        }
                        else {
                            sd._text = otText.type.apply(sd.text ?? '', comp.es) as string;
                            sd.update?.();
                        }
                    }
                }
                else {
                    subDoc = subDoc != null ? subDoc.queryBlock?.([d]) : undefined;
                }
            }

            return rootContainer.root;
        }

        drop(snapshot, operations);

        if (selection) {
            const { anchorPath, anchor, focus, isSelectionInSameBlock } = selection;
            const cursorBlock = this.scrollPage?.queryBlock(anchorPath);

            const begin = Math.min(anchor.offset, focus.offset);
            const end = Math.max(anchor.offset, focus.offset);

            if (isSelectionInSameBlock && cursorBlock && cursorBlock.isContent())
                cursorBlock.setCursor(begin, end, true);
            else
                this.selection.setSelection(selection);
        }
    }

    setContent(content: TState[] | string, autoFocus = false) {
        this.jsonState.setContent(content);
        const state = this.jsonState.getState();

        this.scrollPage!.updateState(state);
        this.history.clear();

        if (autoFocus)
            this.focus();
    }
}

import type Format from '../block/base/format';
import type { Muya } from '../muya';
import { BLOCK_DOM_PROPERTY, CLASS_NAMES } from '../config';
import { findContentDOM } from '../selection/dom';
import { getLinkInfo } from '../utils/getLinkInfo';

// Port of marktext `src/muya/lib/eventHandler/mouseEvent.js` (cb25b3d4
// + the surrounding hover dispatch infrastructure). The new repo's
// linkTools popover subscribes to `muya-link-tools` but had no emitter;
// this module is that emitter.
//
// Three rendered link variants are detected, each by its wrapper class:
//   - markdown `[text](href)`      → span.mu-inline-rule.mu-link
//   - reference link `[label][ref]` → a.mu-inline-rule.mu-reference-link
//                                       (or span.mu-reference-link if href
//                                        is not yet resolved — those are
//                                        intentionally *not* popover targets:
//                                        nothing to jump to or unlink)
//   - HTML `<a href=...>`          → a.mu-inline-rule.mu-raw-html
//
// For the markdown and reference-link variants we additionally require the
// preceding sibling to be `.mu-hide` — i.e. the source-character markers
// are hidden, which means the wrapper is rendered in *preview* mode
// (cursor isn't editing inside the link). This mirrors marktext's
// `parentPreSibling.classList.contains('ag-hide')` guard and keeps the
// popover from flashing while the user types the URL.
//
// Click suppression: PR-11b removed the `pointer-events: none` rule that
// `inlineSyntax.css` used to set on link wrappers, because that rule
// hid all mouse events from us — events hit-tested straight through to
// the editor container. We compensate by `preventDefault()`-ing clicks
// on `a.mu-inline-rule` wrappers (standard contenteditable rich-text
// pattern: clicking a link inside the editor should place the cursor,
// not navigate away).
//
// Cleanup: every listener is attached via `eventCenter.attachDOMEvent`,
// so `muya.destroy()` → `eventCenter.detachAllDomEvents()` removes them.

// `mu-raw-html` is added to every inline HTML tag (`<u>`, `<mark>`,
// `<sub>`, `<sup>`, `<a>` …), so we can't match it loosely — narrow
// each entry by the actual tag the renderer emits.
const LINK_SELECTOR = [
    `span.${CLASS_NAMES.MU_LINK}`,
    `a.${CLASS_NAMES.MU_REFERENCE_LINK}`,
    `a.${CLASS_NAMES.MU_RAW_HTML}`,
].join(', ');

// Click suppression covers all real anchor variants whether or not they
// host a popover (no-text-link is `<a href target=_blank>` and would
// open a tab without this guard).
const ANCHOR_CLICK_SELECTOR = `a.${CLASS_NAMES.MU_INLINE_RULE}`;

function findLinkWrapper(target: EventTarget | null): HTMLElement | null {
    if (!(target instanceof HTMLElement))
        return null;

    return target.closest<HTMLElement>(LINK_SELECTOR);
}

function isPopoverTarget(wrapper: HTMLElement): boolean {
    // HTML `<a>` is always a popover target — no source markers to hide.
    if (wrapper.classList.contains(CLASS_NAMES.MU_RAW_HTML))
        return true;

    // Markdown link / reference link: only show in preview mode (the
    // preceding `[` marker is hidden via `.mu-hide`).
    const prev = wrapper.previousElementSibling;

    return !!prev && prev.classList.contains(CLASS_NAMES.MU_HIDE);
}

export function attachLinkMouseHandlers(muya: Muya): void {
    const { eventCenter, domNode } = muya;

    const overHandler = (event: Event) => {
        const wrapper = findLinkWrapper(event.target);
        if (!wrapper || !isPopoverTarget(wrapper))
            return;

        const linkInfo = getLinkInfo(wrapper);
        if (!linkInfo)
            return;

        // The unlink path needs the containing block so it can rewrite the
        // block's source text. Resolve it via the DOM-attached block ref
        // (the same property `selection/index.ts` uses for image clicks).
        const contentDom = findContentDOM(wrapper);
        const block = (contentDom?.[BLOCK_DOM_PROPERTY] ?? null) as Format | null;

        eventCenter.emit('muya-link-tools', {
            reference: wrapper,
            linkInfo,
            block,
        });
    };

    const outHandler = (event: Event) => {
        const wrapper = findLinkWrapper(event.target);
        if (!wrapper)
            return;

        // Ignore mouseout when the pointer is still inside the same wrapper
        // (e.g. crossing between a `<strong>` and the surrounding text child).
        // Without this guard the popover hides every time the pointer crosses
        // an internal element boundary.
        if (event instanceof MouseEvent) {
            const { relatedTarget } = event;
            if (relatedTarget instanceof Node && wrapper.contains(relatedTarget))
                return;
        }

        eventCenter.emit('muya-link-tools', { reference: null });
    };

    const clickHandler = (event: Event) => {
        if (!(event.target instanceof HTMLElement))
            return;

        if (event.target.closest(ANCHOR_CLICK_SELECTOR))
            event.preventDefault();
    };

    eventCenter.attachDOMEvent(domNode, 'mouseover', overHandler);
    eventCenter.attachDOMEvent(domNode, 'mouseout', outHandler);
    eventCenter.attachDOMEvent(domNode, 'click', clickHandler);
}

// The Quickdraw editor: camera, tools, selection, input and rendering over a
// Store. Framework-free — the React and React Native SDKs wrap it, plain
// pages use it bare, and every host gets the identical feel.
// Dependency-free ESM: runs in any modern browser as-is, no build step.

import { Store, newId } from './store.js'
import { themeOf, SIZES, FONT_SIZES, GEO_IDS, COLOR_IDS, GRID_IDS, GRID_STEP, GRID_MAJOR } from './palette.js'
import {
  localBounds, pageBounds, toLocal, drawShape, hitShape, marqueeHits,
  scaleShape, textLayout, noteLayout, NOTE_W, sampleLinePts,
} from './shapes.js'
import { boundsUnion, boundsExpand, boundsContain, clamp, rotWith } from './geometry.js'

const ZOOM_MIN = 0.05
const ZOOM_MAX = 8
const HANDLE = 8 // screen px
const RESIZE_CURSORS = {
  tl: 'nwse-resize', br: 'nwse-resize', tr: 'nesw-resize', bl: 'nesw-resize',
  t: 'ns-resize', b: 'ns-resize', l: 'ew-resize', r: 'ew-resize',
}
const DEFAULT_STYLES = { color: 'blue', size: 'm', dash: 'draw', fill: 'none', font: 'draw' }

export const TOOLS = ['select', 'hand', 'draw', 'highlight', 'eraser', 'laser', 'arrow', 'line', 'geo', 'text', 'note']

// local position of the bend handle: the curve's midpoint (chord midpoint
// when straight — sampleLinePts collapses to the two endpoints at bend 0)
const bendMidpoint = (pr) => {
  if (!pr.bend) return { x: pr.dx / 2, y: pr.dy / 2 }
  const mid = sampleLinePts(pr, pr.bend)
  const mi = Math.floor(mid.length / 4) * 2
  return { x: mid[mi], y: mid[mi + 1] }
}

export class Editor {
  constructor({ container, store, theme = 'light', grid = 'lines', readonly = false, camera, styles, geoKind } = {}) {
    this.container = container
    this.store = store || new Store()
    this.theme = themeOf(theme)
    this.grid = GRID_IDS.includes(grid) ? grid : 'lines'
    this.readonly = !!readonly
    this.camera = camera || { x: 0, y: 0, z: 1 }
    this.styles = { ...DEFAULT_STYLES, ...(styles || {}) }
    this.geoKind = geoKind || 'rectangle'
    this.tool = 'draw'
    this.selection = new Set()
    this.session = null
    this.editing = null // { id, textarea, field: 'text' | 'label' }
    this.scribbles = [] // local laser strokes
    this.remoteScribbles = []
    this.remoteScribblesAt = 0
    this.spaceHeld = false
    this.captureCanvas = null
    // pen mode: once a stylus is seen, fingers stop drawing — a resting palm
    // is ignored, two fingers still steer the camera. setPenMode(false) opts
    // back out; auto-arm happens only once so that choice sticks.
    this.penMode = false
    this._penSeen = false
    this._penDown = false
    this._events = new Map()
    this._raf = 0
    this._camAnim = 0
    this._pointers = new Map()
    this._ptrType = new Map() // pointerId -> pointerType, for pen-mode gating
    this._destroyed = false

    // DOM
    container.classList.add('qd-root')
    container.tabIndex = 0
    this.canvas = document.createElement('canvas')
    this.canvas.className = 'qd-canvas'
    this.overlay = document.createElement('canvas')
    this.overlay.className = 'qd-overlay'
    container.prepend(this.overlay)
    container.prepend(this.canvas)

    this._bind()
    this._unsubStore = this.store.listen(() => {
      this._pruneSelection()
      this.requestRender()
      this.emit('change')
    })
    // history moves on its own channel: the end of a gesture batch changes
    // canUndo/canRedo without emitting a document diff
    this._unsubHistory = this.store.listenHistory(() => this.emit('history'))
    this.requestRender()
  }

  // ---- events --------------------------------------------------------------
  on(ev, fn) {
    if (!this._events.has(ev)) this._events.set(ev, new Set())
    this._events.get(ev).add(fn)
    return () => this._events.get(ev).delete(fn)
  }
  emit(ev, ...args) {
    const s = this._events.get(ev)
    if (s) for (const fn of [...s]) { try { fn(...args) } catch (e) { console.warn('board event failed', e) } }
  }

  // ---- camera --------------------------------------------------------------
  viewSize() {
    return { w: this.container.clientWidth || 1, h: this.container.clientHeight || 1 }
  }
  screenToPage(sx, sy) {
    const c = this.camera
    return { x: sx / c.z - c.x, y: sy / c.z - c.y }
  }
  pageToScreen(px, py) {
    const c = this.camera
    return { x: (px + c.x) * c.z, y: (py + c.y) * c.z }
  }
  viewportPageBounds() {
    const { w, h } = this.viewSize()
    const c = this.camera
    return { x: -c.x, y: -c.y, w: w / c.z, h: h / c.z }
  }
  setCamera(cam, { animate = 0 } = {}) {
    this._cancelFitEase()
    cancelAnimationFrame(this._camAnim)
    if (!animate) {
      this.camera = { ...cam }
      this._afterCamera()
      return
    }
    const from = { ...this.camera }
    const t0 = performance.now()
    const step = (now) => {
      const t = Math.min(1, (now - t0) / animate)
      const e = 1 - Math.pow(1 - t, 3)
      this.camera = {
        x: from.x + (cam.x - from.x) * e,
        y: from.y + (cam.y - from.y) * e,
        z: from.z + (cam.z - from.z) * e,
      }
      this._afterCamera()
      if (t < 1) this._camAnim = requestAnimationFrame(step)
    }
    this._camAnim = requestAnimationFrame(step)
  }
  _afterCamera() {
    this.requestRender()
    this.emit('camera')
  }
  pan(dxScreen, dyScreen) {
    const c = this.camera
    this.setCamera({ ...c, x: c.x + dxScreen / c.z, y: c.y + dyScreen / c.z })
  }
  zoomAt(sx, sy, mult, opts) {
    const c = this.camera
    const z = clamp(c.z * mult, ZOOM_MIN, ZOOM_MAX)
    const p = this.screenToPage(sx, sy)
    this.setCamera({ z, x: sx / z - p.x, y: sy / z - p.y }, opts)
  }
  contentBounds() {
    let b = null
    for (const s of this.store.shapes()) b = boundsUnion(b, pageBounds(s))
    return b
  }
  // Re-fit the camera to the drawn content with a margin — the transition
  // companion. Zoom capped at 1:1 so a lone small mark doesn't blow up.
  // `ease` (ms): one rAF loop owns the camera for the whole beat — the fit
  // target re-reads the live-resizing frame every frame, the camera's
  // starting offset from it decays once, and the render happens in the same
  // frame as the camera write. Resize ticks that arrive while the ease is
  // running are no-ops; a second driver on another clock reads as judder.
  fitContent({ margin = 0.08, maxZoom = 1, animate = 0, ease = 0 } = {}) {
    // called before the container has layout (mount effects, hidden tabs):
    // defer until the first render tick that sees real dimensions, or the
    // camera would clamp to minimum zoom and strand the drawing microscopic
    if (this._deferFit(() => this.fitContent({ margin, maxZoom, animate, ease }))) return
    const fitNow = () => {
      const b = this.contentBounds()
      if (!b || b.w <= 0 || b.h <= 0) return null
      const { w, h } = this.viewSize()
      const inset = Math.min(w, h) * margin
      const z = clamp(Math.min(maxZoom, (w - inset * 2) / b.w, (h - inset * 2) / b.h), ZOOM_MIN, ZOOM_MAX)
      if (!isFinite(z) || z <= 0) return null
      return { z, x: w / 2 / z - (b.x + b.w / 2), y: h / 2 / z - (b.y + b.h / 2) }
    }
    if (!ease) {
      const fit = fitNow()
      if (fit) this.setCamera(fit, { animate })
      return
    }
    this._easeToFit(fitNow, ease)
  }
  // Fit an explicit page rect into the view — e.g. a remote peer's viewport,
  // mirrored live. Cover-fit: the rect's center stays centered and the
  // frame fills edge to edge, so differing aspect ratios crop rather than
  // letterbox. `ease` tracks a live frame resize exactly like fitContent's.
  followBounds(b, { animate = 0, ease = 0 } = {}) {
    if (!b || !(b.w > 0) || !(b.h > 0)) return
    if (this._deferFit(() => this.followBounds(b, { animate, ease }))) return
    const fitNow = () => {
      const { w, h } = this.viewSize()
      const z = clamp(Math.max(w / b.w, h / b.h), ZOOM_MIN, ZOOM_MAX)
      if (!isFinite(z) || z <= 0) return null
      return { z, x: w / 2 / z - (b.x + b.w / 2), y: h / 2 / z - (b.y + b.h / 2) }
    }
    if (!ease) {
      const fit = fitNow()
      if (fit) this.setCamera(fit, { animate })
      return
    }
    this._easeToFit(fitNow, ease)
  }
  // true (and remembers the retry) while the container has no layout yet;
  // render() replays the latest pending fit once real dimensions appear
  _deferFit(retry) {
    const { w, h } = this.viewSize()
    if (w > 1 && h > 1) return false
    this._pendingFit = retry
    return true
  }
  // one rAF loop owns the camera for the whole beat: the fit target re-reads
  // the live-resizing frame every frame, the starting offset decays once
  _easeToFit(fitNow, ease) {
    if (this._fitEase) return // the loop below is already tracking the frame
    const fit0 = fitNow()
    if (!fit0) return
    const c = this.camera
    const fe = this._fitEase = { t0: 0, dur: ease, dx: c.x - fit0.x, dy: c.y - fit0.y, dz: c.z - fit0.z }
    cancelAnimationFrame(this._camAnim)
    const step = (now) => {
      if (this._fitEase !== fe || this._destroyed) return
      if (!fe.t0) fe.t0 = now
      const t = Math.min(1, (now - fe.t0) / fe.dur)
      const e = 1 - Math.pow(1 - t, 3)
      const fit = fitNow()
      if (fit) {
        this.camera = {
          z: fit.z + fe.dz * (1 - e),
          x: fit.x + fe.dx * (1 - e),
          y: fit.y + fe.dy * (1 - e),
        }
        this.render()
        this.emit('camera')
      }
      if (t < 1) this._fitEaseRaf = requestAnimationFrame(step)
      else this._fitEase = null
    }
    this._fitEaseRaf = requestAnimationFrame(step)
  }
  _cancelFitEase() {
    this._fitEase = null
    cancelAnimationFrame(this._fitEaseRaf)
  }
  // ---- tools / styles ------------------------------------------------------
  setTool(tool) {
    if (!TOOLS.includes(tool)) return
    this._commitText()
    this.tool = tool
    if (tool !== 'select') this.setSelection([])
    this._syncCursor()
    this.emit('tool')
    this.requestRender()
  }
  setGeoKind(kind) {
    if (GEO_IDS.includes(kind)) { this.geoKind = kind; this.emit('tool') }
  }
  setTheme(id) {
    const t = themeOf(id)
    if (t === this.theme) return
    this._crossfadeTheme()
    this.theme = t
    this.container.dataset.qdTheme = t.id
    this.requestRender()
    this.emit('theme')
  }
  // Freeze the outgoing theme as a bitmap over the board and fade it out, so
  // a theme switch melts from one paper to the other instead of hard-cutting.
  _crossfadeTheme() {
    if (this._destroyed) return
    if (typeof window !== 'undefined' &&
        window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return
    const w = this.canvas.width, h = this.canvas.height
    if (!w || !h) return
    try {
      const snap = document.createElement('canvas')
      snap.width = w
      snap.height = h
      snap.getContext('2d').drawImage(this.canvas, 0, 0)
      snap.className = 'qd-theme-fade'
      this._themeFade?.remove()
      this._themeFade = snap
      this.overlay.after(snap)
      // two frames: one to paint at full opacity, one to start the transition
      requestAnimationFrame(() => requestAnimationFrame(() => { snap.style.opacity = '0' }))
      const done = () => {
        snap.remove()
        if (this._themeFade === snap) this._themeFade = null
      }
      snap.addEventListener('transitionend', done, { once: true })
      setTimeout(done, 600) // safety net if transitionend never fires
    } catch {
      // a stubbed 2D context (tests, exotic embeds) just skips the fade
    }
  }
  // 'none' | 'lines' | 'dots' — the backdrop behind the drawing
  setGrid(id) {
    if (!GRID_IDS.includes(id) || id === this.grid) return
    this.grid = id
    this.requestRender()
    this.emit('grid')
  }
  setReadonly(ro) {
    this.readonly = !!ro
    if (ro) { this._cancelSession(); this._commitText(); this.setSelection([]) }
    this._syncCursor()
  }
  setPenMode(on) {
    on = !!on
    if (this.penMode === on) return
    this.penMode = on
    this.emit('penmode')
  }
  // pointers eligible for the two-finger pinch: in pen mode the pen itself
  // never counts — only fingers steer the camera
  _pinchPoints() {
    const pts = []
    for (const [id, p] of this._pointers) {
      if (this.penMode && this._ptrType.get(id) === 'pen') continue
      pts.push(p)
    }
    return pts
  }
  setStyle(key, value) {
    this.styles = { ...this.styles, [key]: value }
    if (this.selection.size) {
      const APPLIES = {
        color: ['draw', 'highlight', 'geo', 'arrow', 'line', 'text', 'note'],
        size: ['draw', 'highlight', 'geo', 'arrow', 'line', 'text', 'note'],
        dash: ['draw', 'geo', 'arrow', 'line'],
        fill: ['geo'],
        font: ['text', 'note', 'geo'],
      }
      this.store.transact(() => {
        for (const id of this.selection) {
          const s = this.store.get(id)
          if (s && APPLIES[key]?.includes(s.type)) this.store.update(id, { props: { [key]: value } })
        }
      })
    }
    this.emit('styles')
  }
  // shared styles of the selection (null value = mixed), or the pen styles
  currentStyles() {
    if (!this.selection.size) return { ...this.styles }
    const out = {}
    for (const id of this.selection) {
      const s = this.store.get(id)
      if (!s) continue
      for (const k of ['color', 'size', 'dash', 'fill', 'font']) {
        if (s.props[k] === undefined) continue
        if (!(k in out)) out[k] = s.props[k]
        else if (out[k] !== s.props[k]) out[k] = null
      }
    }
    return { ...this.styles, ...out }
  }

  // ---- selection -----------------------------------------------------------
  setSelection(ids) {
    this.selection = new Set(ids)
    this.requestRender()
    this.emit('selection')
  }
  _pruneSelection() {
    let dirty = false
    for (const id of this.selection) if (!this.store.has(id)) { this.selection.delete(id); dirty = true }
    if (dirty) this.emit('selection')
  }
  selectionBounds() {
    let b = null
    for (const id of this.selection) {
      const s = this.store.get(id)
      if (s) b = boundsUnion(b, pageBounds(s))
    }
    return b
  }
  deleteSelection() {
    if (!this.selection.size) return
    this.store.remove([...this.selection])
    this.setSelection([])
  }
  // Empties the board in one undoable step (⇧⌘⌫, or the board menu).
  clearBoard() {
    if (!this.store.ids().length) return
    this._cancelSession()
    this._commitText()
    this.store.clear()
    this.setSelection([])
  }
  selectAll() {
    if (this.tool !== 'select') this.setTool('select')
    this.setSelection(this.store.shapes().map((s) => s.id))
  }
  duplicateSelection(offset = 16) {
    if (!this.selection.size) return
    const ids = []
    let z = this.store.maxZ()
    this.store.transact(() => {
      for (const id of this.selection) {
        const s = this.store.get(id)
        if (!s || s.typeName === 'asset') continue
        const copy = { ...s, id: newId(), x: s.x + offset, y: s.y + offset, z: ++z }
        this.store.put(copy)
        ids.push(copy.id)
      }
    })
    this.setSelection(ids)
  }
  bringToFront() {
    let z = this.store.maxZ()
    const sel = this.store.shapes().filter((s) => this.selection.has(s.id)).sort((a, b) => a.z - b.z)
    this.store.transact(() => { for (const s of sel) this.store.update(s.id, { z: ++z }) })
  }
  sendToBack() {
    let z = this.store.minZ()
    const sel = this.store.shapes().filter((s) => this.selection.has(s.id)).sort((a, b) => b.z - a.z)
    this.store.transact(() => { for (const s of sel) this.store.update(s.id, { z: --z }) })
  }

  shapesSorted() {
    // highlighter lives under the ink, like on paper — highlights render
    // first (in their own z order), everything else above
    return this.store.shapes().sort(
      (a, b) =>
        (a.type === 'highlight' ? 0 : 1) - (b.type === 'highlight' ? 0 : 1) ||
        a.z - b.z ||
        (a.id < b.id ? -1 : 1)
    )
  }
  hitTest(px, py) {
    const tol = 8 / this.camera.z
    const list = this.shapesSorted()
    for (let i = list.length - 1; i >= 0; i--) {
      if (hitShape(list[i], px, py, tol, this.store)) return list[i]
    }
    return null
  }

  // ---- input ---------------------------------------------------------------
  _bind() {
    const c = this.container
    this._onDown = (e) => this._pointerDown(e)
    this._onMove = (e) => this._pointerMove(e)
    this._onUp = (e) => this._pointerUp(e)
    this._onWheel = (e) => this._wheel(e)
    this._onKeyDown = (e) => this._keyDown(e)
    this._onKeyUp = (e) => this._keyUp(e)
    this._onDblClick = (e) => this._dblClick(e)
    this._onDrop = (e) => this._drop(e)
    this._onDragOver = (e) => { e.preventDefault(); e.stopPropagation() }
    this._onPaste = (e) => this._paste(e)
    c.addEventListener('pointerdown', this._onDown)
    c.addEventListener('pointermove', this._onMove)
    c.addEventListener('pointerup', this._onUp)
    c.addEventListener('pointercancel', this._onUp)
    c.addEventListener('wheel', this._onWheel, { passive: false })
    c.addEventListener('keydown', this._onKeyDown)
    c.addEventListener('keyup', this._onKeyUp)
    c.addEventListener('dblclick', this._onDblClick)
    c.addEventListener('drop', this._onDrop)
    c.addEventListener('dragover', this._onDragOver)
    c.addEventListener('paste', this._onPaste)
    // losing focus mid-gesture (a host app may reclaim the space key by
    // blurring the board) must not leave a sticky space-pan behind
    this._onBlur = () => { this.spaceHeld = false; this._syncCursor() }
    c.addEventListener('blur', this._onBlur)
    this._ro = new ResizeObserver(() => this.requestRender())
    this._ro.observe(c)
  }

  _evPoint(e) {
    const r = this.container.getBoundingClientRect()
    return { x: e.clientX - r.left, y: e.clientY - r.top }
  }

  _pointerDown(e) {
    if (this.readonly) return
    if (e.target !== this.canvas && e.target !== this.overlay && e.target !== this.container) return
    if (e.button === 2) return
    if (this.editing) this._commitText()
    this.container.focus({ preventScroll: true })
    const s = this._evPoint(e)
    this._pointers.set(e.pointerId, s)
    this._ptrType.set(e.pointerId, e.pointerType)
    try { this.container.setPointerCapture(e.pointerId) } catch {}

    if (e.pointerType === 'pen') {
      this._penDown = true
      // first stylus contact arms pen mode, once — turning it off is a choice
      if (!this._penSeen) { this._penSeen = true; this.setPenMode(true) }
    }

    // second finger: the gesture becomes a pinch — a just-started stroke is
    // taken back, it was the start of a zoom, not a mark. While the pen is
    // down in pen mode, landing fingers are a resting palm, never a pinch.
    if (!this.penMode || e.pointerType !== 'pen') {
      const pp = this._pinchPoints()
      if (pp.length === 2 && !(this.penMode && this._penDown)) {
        this._abortForPinch()
        const [a, b] = pp
        this.session = {
          type: 'pinch',
          dist: Math.hypot(a.x - b.x, a.y - b.y),
          center: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 },
          cam: { ...this.camera },
        }
        return
      }
      if (pp.length > 2) return
    }
    // in pen mode a finger never draws
    if (this.penMode && e.pointerType === 'touch') return
    if (this._pointers.size > 2) return
    if (this.session?.type === 'pinch') return

    const p = this.screenToPage(s.x, s.y)
    if (e.button === 1 || this.spaceHeld || this.tool === 'hand') {
      this.session = { type: 'panning', last: s }
      this._syncCursor('grabbing')
      return
    }

    switch (this.tool) {
      case 'draw':
      case 'highlight': return this._beginDraw(e, p)
      case 'eraser': return this._beginErase(p)
      case 'laser': return this._beginLaser(p)
      case 'arrow':
      case 'line': return this._beginLineish(this.tool, p, e)
      case 'geo': return this._beginGeo(p, e)
      // placing waits for pointerup: the textarea we focus would otherwise be
      // blurred again by the browser's default focus-on-mousedown action
      case 'text':
      case 'note':
        this.session = { type: 'placing', tool: this.tool, page: p }
        return
      case 'select': return this._beginSelect(e, s, p)
    }
  }

  _pointerMove(e) {
    if (this.readonly) return
    if (this._pointers.has(e.pointerId)) this._pointers.set(e.pointerId, this._evPoint(e))
    const ss = this.session
    if (!ss) {
      this._hoverCursor(e)
      return
    }
    // in pen mode a finger only ever steers the camera — a palm dragging
    // across the glass must not extend the pen's stroke
    if (this.penMode && e.pointerType === 'touch' && ss.type !== 'pinch' && ss.type !== 'panning') return
    const s = this._evPoint(e)
    const p = this.screenToPage(s.x, s.y)

    switch (ss.type) {
      case 'pinch': {
        const pp = this._pinchPoints()
        if (pp.length < 2) return
        const [a, b] = pp
        const dist = Math.hypot(a.x - b.x, a.y - b.y) || 1
        const center = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
        const z = clamp(ss.cam.z * (dist / ss.dist), ZOOM_MIN, ZOOM_MAX)
        // keep the page point under the initial pinch center pinned, then pan
        // with the center as it travels
        const p0 = { x: ss.center.x / ss.cam.z - ss.cam.x, y: ss.center.y / ss.cam.z - ss.cam.y }
        this.setCamera({ z, x: center.x / z - p0.x, y: center.y / z - p0.y })
        return
      }
      case 'panning': {
        this.pan(s.x - ss.last.x, s.y - ss.last.y)
        ss.last = s
        return
      }
      case 'drawing': return this._extendDraw(e, p)
      case 'erasing': return this._extendErase(p)
      case 'lasering': return this._extendLaser(p)
      case 'lineish': return this._dragLineish(p, e)
      case 'geo-create': return this._dragGeo(p, e)
      case 'marquee': {
        ss.rect = {
          x: Math.min(ss.origin.x, p.x), y: Math.min(ss.origin.y, p.y),
          w: Math.abs(p.x - ss.origin.x), h: Math.abs(p.y - ss.origin.y),
        }
        const hits = this.shapesSorted().filter((sh) => marqueeHits(sh, ss.rect)).map((sh) => sh.id)
