  _toggled(id) {
    const next = new Set(this.selection)
    next.has(id) ? next.delete(id) : next.add(id)
    return [...next]
  }

  _abortForPinch() {
    const ss = this.session
    if (!ss) return
    if (ss.type === 'drawing') {
      this.store.remove([ss.id])
      this.store.endBatch()
    } else if (ss.type === 'lineish' || ss.type === 'geo-create') {
      this.store.remove([ss.id])
      this.store.endBatch()
