      id, typeName: 'shape', type: 'geo', x: p.x, y: p.y, rot: 0, z: this.store.maxZ() + 1,
      props: {
        geo: this.geoKind, w: 1, h: 1,
        color: this.styles.color, size: this.styles.size,
        dash: this.styles.dash, fill: this.styles.fill, font: this.styles.font,
